// "Ask the data": turn a plain-English question into an indicator, places and years,
// then answer ONLY from the loaded data rows. No number is ever generated by a model here.
// If an AI chat API is configured (assets/config.js), questions go there first and this
// engine is the fallback.

import { normalize, SOURCE_NAMES, dimsText } from "./data.js";
import { fmt, unitSuffix, pctChange, cagr, esc } from "./format.js";

const STOP = new Set(`a an the of in on for to and or vs versus compare comparison between with by
from since until till through what whats is are was were how much many show me give tell data
about which who where latest recent most current trend trends over time change changed growth grew
rate rates level levels value values country countries region regions world global globally
year years please do does did between top highest lowest least best worst rank ranking ranked
there share has have had all its it per capita than more less then`.split(/\s+/));

const KEEP_IN_NAME = new Set(["per", "capita", "share", "rate"]);
// Words that pick a breakdown (rural, female...) rather than the measure itself.
const BREAKDOWN_WORDS = new Set(["urban", "rural", "female", "male", "women", "men", "sex", "age",
  "location", "area", "areas"]);

const SYNONYMS = {
  renewables: ["renewable"], renewable: ["renewable"], emissions: ["emission", "emissions"],
  co2: ["co2", "carbon", "dioxide"], carbon: ["co2", "carbon"], ghg: ["greenhouse", "gas"],
  greenhouse: ["greenhouse"], electricity: ["electricity"], electrification: ["electricity", "access"],
  forests: ["forest"], deforestation: ["forest"], women: ["women", "female"], girls: ["female", "girls"],
  poor: ["poverty"], hunger: ["undernourishment", "hunger"], undernourished: ["undernourishment"],
  water: ["water", "drinking"], sanitation: ["sanitation"], clean: ["clean"], cooking: ["cooking"],
  pollution: ["pollution", "pm2.5"], pm25: ["pm2.5"], solar: ["solar"], wind: ["wind"],
  coal: ["coal"], oil: ["oil"], gas: ["gas"], energy: ["energy"], fossil: ["fossil"],
  mortality: ["mortality"], deaths: ["mortality", "deaths"], temperature: ["temperature"],
  warming: ["temperature"], parliament: ["parliaments", "seats"], gdp: ["gdp"],
  population: ["population"], marine: ["marine"], ocean: ["marine", "ocean"],
  person: ["capita", "person"], head: ["capita"], people: ["population", "people"],
  cooking: ["cooking", "clean", "fuel"], fuels: ["fuel"],
  protected: ["protected"], biodiversity: ["biodiversity", "protected", "species"],
};

function stem(w) {
  if (w.length > 4 && w.endsWith("ies")) return w.slice(0, -3) + "y";
  if (w.length > 3 && w.endsWith("es") && !w.endsWith("ses")) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith("s") && !w.endsWith("ss")) return w.slice(0, -1);
  return w;
}

const nameTokenCache = new Map();
function nameTokens(ind) {
  if (!nameTokenCache.has(ind.id)) {
    const words = normalize(`${ind.n} ${ind.c} ${(ind.tp || []).join(" ")}`).split(" ").map(stem);
    nameTokenCache.set(ind.id, { set: new Set(words), list: words });
  }
  return nameTokenCache.get(ind.id);
}

export function parseYears(q) {
  const yrs = [...q.matchAll(/\b(1[89]\d{2}|20\d{2})\b/g)].map((m) => +m[1]);
  const since = /\b(since|from|after)\s+(1[89]\d{2}|20\d{2})/.exec(q);
  const until = /\b(until|till|to|through|before)\s+(1[89]\d{2}|20\d{2})/.exec(q);
  const range = /\b(1[89]\d{2}|20\d{2})\s*(?:-|–|to|and)\s*(1[89]\d{2}|20\d{2})\b/.exec(q);
  if (range) return { y0: +range[1], y1: +range[2] };
  if (since && !until) return { y0: +since[2], y1: null };
  if (yrs.length === 1) return { y0: yrs[0], y1: yrs[0], single: true };
  if (yrs.length >= 2) return { y0: Math.min(...yrs), y1: Math.max(...yrs) };
  const last = /\blast\s+(\d{1,2})\s+years?\b/.exec(q);
  if (last) return { lastN: +last[1] };
  return {};
}

export function findGeos(store, question) {
  const words = normalize(question).split(" ");
  const raw = question;
  const found = [];
  const used = new Array(words.length).fill(false);
  for (let n = 6; n >= 1; n--) {
    for (let i = 0; i + n <= words.length; i++) {
      if (used.slice(i, i + n).some(Boolean)) continue;
      const phrase = words.slice(i, i + n).join(" ");
      let code = store.geoAlias.get(phrase);
      if (["world", "global", "globally", "worldwide", "earth"].includes(phrase)) code = "WORLD";
      if (!code) continue;
      // Short aliases (US, UK, EU...) only count when typed in capitals.
      if (phrase.length <= 3 && code !== "WORLD" &&
          !new RegExp(`\\b${phrase.toUpperCase().replace(/\./g, "\\.")}\\b`).test(raw)) continue;
      found.push({ code, at: i, text: phrase });
      for (let k = i; k < i + n; k++) used[k] = true;
    }
  }
  found.sort((a, b) => a.at - b.at);
  return { geos: [...new Set(found.map((f) => f.code))], usedWords: words.filter((_, i) => used[i]) };
}

export function scoreIndicators(store, question, geoWords) {
  const q = normalize(question);
  const goalMatch = /\b(?:sdg|goal)\s*(\d{1,2})\b/.exec(q);
  const goal = goalMatch ? goalMatch[1] : null;
  const geoSet = new Set(geoWords.flatMap((w) => w.split(" ")));
  let tokens = q.split(" ").filter((w) => w && !geoSet.has(w) && !/^\d{4}$/.test(w));
  const wantsPerCapita = /per capita|per person|per head/.test(q);
  const wantsShare = /\bshare\b|\bpercent|%|proportion/.test(q);
  tokens = tokens.filter((w) => (!STOP.has(w) || KEEP_IN_NAME.has(w)) && !BREAKDOWN_WORDS.has(w));
  // "women in parliament" is about the measure, not a breakdown: keep it when nothing else is left
  if (!tokens.length && /\bwomen\b/.test(q)) tokens = ["women"];
  const expanded = [];
  tokens.forEach((w) => {
    const s = stem(w);
    const syn = SYNONYMS[w] || SYNONYMS[s];
    expanded.push(syn ? syn.map(stem) : [s]);
  });
  if (!expanded.length && !goal) return [];
  const results = [];
  for (const ind of store.indicators) {
    if (goal && !(ind.g || []).includes(goal)) continue;
    const { set, list } = nameTokens(ind);
    let score = 0;
    let hits = 0;
    for (const alts of expanded) {
      if (alts.some((a) => set.has(a))) {
        score += 3;
        hits += 1;
      }
    }
    if (!hits && !goal) continue;
    if (expanded.length > 1 && hits === expanded.length) score += 3;
    const name = normalize(ind.n);
    if (wantsPerCapita && /per capita|per person/.test(name)) score += 3;
    if (!wantsPerCapita && /per capita|per person/.test(name)) score -= 2;
    if (wantsShare && /share|%|percent|proportion/.test(name)) score += 2;
    if (/growth|annual change|cumulative|_growth/.test(ind.c) || /growth|cumulative/.test(name)) score -= 2;
    score -= list.length * 0.06;
    if (!ind.has_total) score -= 1;
    score += Math.min(ind.ng || 0, 200) / 200;
    score += ind.y1 >= 2020 ? 0.5 : 0;
    score += { unsdg: 0.4, wdi: 0.2, owid: 0 }[ind.s] || 0;
    results.push({ ind, score, hits });
  }
  results.sort((a, b) => b.score - a.score);
  return results;
}

function intentOf(q, geos, years) {
  const top = /\b(top|highest|largest|biggest|most|best)\b(?:\s+(\d{1,2}))?/.exec(q);
  const bottom = /\b(lowest|smallest|least|worst|bottom)\b(?:\s+(\d{1,2}))?/.exec(q);
  const nMatch = /\b(?:top|bottom)\s+(\d{1,2})\b/.exec(q);
  if ((top || bottom || /\brank|ranking|which countr/.test(q)) && geos.length <= 1) {
    return { kind: "rank", dir: bottom && !top ? "asc" : "desc", n: nMatch ? +nMatch[1] : 10 };
  }
  if (/\b(trend|over time|since|change|grew|growth|increase|decrease|decline|evolve)/.test(q) ||
      (years.y0 && years.y1 && years.y0 !== years.y1) || years.lastN) {
    return { kind: "trend" };
  }
  if (geos.length > 1 || /\bvs\b|versus|compare/.test(q)) return { kind: "compare" };
  return { kind: "value" };
}

function resolveWorld(code, series) {
  if (code !== "WORLD") return code;
  const pref = { unsdg: "UN-001", wdi: "WB-WLD", owid: "OWID-World" }[series.source];
  if (series.geos.includes(pref)) return pref;
  return series.geos.find((g) => /World/.test(g)) || "UN-001";
}

function expandRegion(store, code, series, wantMembers = false) {
  if (series.geos.includes(code) && !wantMembers) return [code];
  const g = store.geoByCode.get(code);
  if (g && g.members && g.members.length) {
    const have = g.members.filter((m) => series.geos.includes(m));
    if (have.length) return have;
  }
  return [code];
}

function pickDims(series, question) {
  if (series.dims.includes("")) {
    const q = normalize(question);
    // Honour an explicit breakdown word ("female", "rural") if the series has it.
    const want = ["female", "male", "rural", "urban"].find((w) => new RegExp(`\\b${w}\\b`).test(q));
    if (want) {
      const d = series.dims.find((x) => new RegExp(`=${want}$|=${want};`, "i").test(x));
      if (d) return d;
    }
    return "";
  }
  return series.dims[0];
}

export function computeAnswer(store, ind, series, plan) {
  const rows = series._rows.filter((r) => r.dims === plan.dims);
  const unit = series.unit;
  const byGeo = new Map();
  rows.forEach((r) => {
    if (!byGeo.has(r.geo)) byGeo.set(r.geo, []);
    byGeo.get(r.geo).push(r);
  });
  byGeo.forEach((list) => list.sort((a, b) => a.year - b.year));
  const maxYear = rows.reduce((m, r) => Math.max(m, r.year), -Infinity);
  const y1 = plan.y1 ?? maxYear;
  const y0 = plan.y0 ?? (plan.lastN ? y1 - plan.lastN : null);
  const lines = [];
  const used = [];
  let flagged = false;
  const name = (c) => store.geoName(c);

  const latestIn = (g, upto, from = -Infinity) => {
    const list = (byGeo.get(g) || []).filter((r) => r.year <= upto && r.year >= from);
    return list[list.length - 1];
  };

  if (plan.intent.kind === "rank") {
    const candidates = [...byGeo.keys()].filter((g) => store.geoByCode.get(g)?.type === "country");
    // Use the latest year that has at least 60% of the best year's coverage.
    const counts = new Map();
    rows.forEach((r) => {
      if (candidates.includes(r.geo)) counts.set(r.year, (counts.get(r.year) || 0) + 1);
    });
    const best = Math.max(0, ...counts.values());
    const yr = [...counts.entries()].filter(([y, c]) => c >= best * 0.6 && y <= y1)
      .map(([y]) => y).sort((a, b) => b - a)[0];
    const all = candidates.map((g) => (byGeo.get(g) || []).find((r) => r.year === yr))
      .filter(Boolean)
      .sort((a, b) => (plan.intent.dir === "asc" ? a.value - b.value : b.value - a.value));
    const vals = all.slice(0, plan.intent.n);
    const ties = all.length ? all.filter((r) => r.value === all[0].value).length : 0;
    if (!vals.length) return { ok: false, text: "No country values are available for that indicator." };
    const nC = counts.get(yr);
    lines.push(`<p>${plan.intent.dir === "asc" ? "Lowest" : "Highest"} ${vals.length === 1 ? "value" : `${vals.length} countries`} in ${yr}, out of ${nC} ${nC === 1 ? "country" : "countries"} with data:</p><ol class="rank">` +
      vals.map((r) => {
        used.push(r);
        flagged ||= !!r.flag;
        return `<li><span>${esc(name(r.geo))}</span><b>${fmt(r.value, unit)}${unitSuffix(unit)}</b></li>`;
      }).join("") + "</ol>" +
      (ties > 1 && ties >= vals.length ? `<p>${ties} countries share the ${plan.intent.dir === "asc" ? "lowest" : "highest"} value (${fmt(all[0].value, unit)}${unitSuffix(unit)}), so the order above is alphabetical. Try the lowest values instead, or a narrower question.</p>` : ""));
    return { ok: true, html: lines.join(""), used, flagged, view: { geos: vals.map((v) => v.geo), y0: yr, y1: yr, mode: "chart" } };
  }

  if (plan.intent.kind === "trend") {
    const from = y0 ?? (byGeo.size ? Math.min(...rows.map((r) => r.year)) : null);
    const parts = [];
    for (const g of plan.geos) {
      const list = (byGeo.get(g) || []).filter((r) => r.year >= from && r.year <= y1);
      if (list.length < 2) {
        parts.push(`<li><span>${esc(name(g))}</span> not enough data between ${from} and ${y1}.</li>`);
        continue;
      }
      const a = list[0];
      const b = list[list.length - 1];
      used.push(a, b);
      flagged ||= !!(a.flag || b.flag);
      const ch = b.value - a.value;
      const pct = pctChange(a.value, b.value);
      const g2 = cagr(a.value, b.value, b.year - a.year);
      const isPct = /percent|%/i.test(series.unit || "");
      const sign = (x) => (x >= 0 ? "+" : "−") + fmt(Math.abs(x));
      const change = isPct ? `${sign(ch)} percentage points` : pct === null ? "" : `${sign(pct)}%`;
      const yearly = !isPct && g2 !== null ? `, ${sign(g2)}% a year` : "";
      const verb = ch > 0 ? "rose" : ch < 0 ? "fell" : "was unchanged";
      parts.push(`<li><span>${esc(name(g))}</span> ${verb} from ${fmt(a.value, unit)}${unitSuffix(unit)} in ${a.year} to <b>${fmt(b.value, unit)}</b> in ${b.year}` +
        `${change ? ` <em>(${change}${yearly})</em>` : ""}</li>`);
    }
    lines.push(`<ul class="trend">${parts.join("")}</ul>`);
    return { ok: used.length > 0, html: lines.join(""), used, flagged, view: { geos: plan.geos, y0: from, y1, mode: "chart" } };
  }

  // value / compare: latest value up to y1 (or the asked year) for each place
  const items = [];
  for (const g of plan.geos) {
    const r = plan.single ? (byGeo.get(g) || []).find((x) => x.year === y1) : latestIn(g, y1);
    if (!r) {
      items.push(`<li><span>${esc(name(g))}</span> no data${plan.single ? ` for ${y1}` : ""}.</li>`);
      continue;
    }
    used.push(r);
    flagged ||= !!r.flag;
    items.push(`<li><span>${esc(name(g))}</span> <b>${fmt(r.value, unit)}</b>${unitSuffix(unit)} in ${r.year}${r.flag ? ` <em>(${flagText(r.flag)})</em>` : ""}</li>`);
  }
  let lead = "";
  const withData = used.filter(Boolean);
  if (plan.intent.kind === "compare" && withData.length > 1) {
    const hi = [...withData].sort((a, b) => b.value - a.value)[0];
    lead = `<p>${esc(name(hi.geo))} has the highest value of the places compared.</p>`;
  }
  lines.push(`<ul class="values">${items.join("")}</ul>${lead}`);
  const yrs = withData.map((r) => r.year);
  return {
    ok: withData.length > 0, html: lines.join(""), used, flagged,
    view: { geos: plan.geos, y0: yrs.length ? Math.min(...yrs) - 15 : null, y1, mode: "chart" },
  };
}

function flagText(f) {
  return { E: "estimate", M: "modelled", "<": "below this value", ">": "above this value",
    G: "global monitoring data", C: "country data", CA: "country-adjusted", N: "non-relevant" }[f] || f;
}

export async function askLocal(store, question, opts = {}) {
  const q = normalize(question);
  const years = parseYears(q);
  const { geos: rawGeos, usedWords } = findGeos(store, question);
  let scored = scoreIndicators(store, question, usedWords);
  if (opts.indicator && store.byId.has(opts.indicator)) {
    scored = [{ ind: store.byId.get(opts.indicator), score: 99 },
      ...scored.filter((s) => s.ind.id !== opts.indicator)];
  }
  if (!scored.length || scored[0].score < 2.5) {
    return {
      ok: false,
      html: `<p>I couldn't match that to an indicator in the database. Try naming the measure, for example “CO2 emissions per capita”, “access to electricity” or “forest area”, or browse the goals below.</p>`,
    };
  }
  const alternatives = scored.slice(1, 4).map((s) => s.ind.id);
  const ind = scored[0].ind;
  const series = await store.series(ind.id);
  const wantMembers = /\bcountries\b|\beach country\b/.test(q) && rawGeos.length === 1;
  let geos = rawGeos.map((g) => resolveWorld(g, series)).flatMap((g) => expandRegion(store, g, series, wantMembers));
  geos = [...new Set(geos)].slice(0, 25);
  const intent = intentOf(q, geos, years);
  if (!geos.length && intent.kind !== "rank") {
    const w = resolveWorld("WORLD", series);
    if (series.geos.includes(w)) geos = [w];
    else if (series.geos.filter((g) => store.geoByCode.get(g)?.type === "country").length >= 10) {
      intent.kind = "rank"; intent.dir = "desc"; intent.n = 10;
    } else geos = series.geos.slice(0, 12);
  }
  const dims = pickDims(series, question);
  const plan = { geos, intent, dims, y0: years.y0 ?? null, y1: years.y1 ?? null,
    single: !!years.single, lastN: years.lastN };
  const pairs = [["urban", "rural"], ["female", "male"]];
  const pair = pairs.find(([a, b]) => new RegExp(`\\b${a}\\b`).test(q) && new RegExp(`\\b${b}\\b`).test(q));
  let res;
  if (pair && plan.intent.kind !== "rank") {
    const parts = pair.map((w) => series.dims.find((x) => new RegExp(`=${w}$|=${w};`, "i").test(x))).filter(Boolean);
    if (parts.length === 2) {
      const subs = parts.map((d) => ({ d, r: computeAnswer(store, ind, series, { ...plan, dims: d }) }));
      res = {
        ok: subs.some((x) => x.r.ok),
        html: subs.map((x) => `<p><b>${esc(dimsText(x.d, series.dim_labels))}</b></p>${x.r.html || ""}`).join(""),
        used: subs.flatMap((x) => x.r.used || []),
        flagged: subs.some((x) => x.r.flagged),
        view: subs[0].r.view,
      };
      plan.dims = parts[0];
    }
  }
  res ||= computeAnswer(store, ind, series, plan);
  const interp = `${esc(ind.n)}${plan.dims ? ` · ${esc(dimsText(plan.dims, series.dim_labels))}` : ""}`;
  return {
    ...res,
    indicator: ind.id,
    dims: plan.dims,
    alternatives,
    interp,
    citation: citation(ind, series),
  };
}

export function citation(ind, series) {
  return {
    source: SOURCE_NAMES[ind.s] || ind.s,
    org: series.source_org,
    code: ind.c,
    release: series.release || ind.rel,
    url: series.source_url,
    updated: series.updated,
  };
}

export async function askApi(apiUrl, question, view) {
  const r = await fetch(apiUrl.replace(/\/$/, "") + "/ask", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ question, view }),
  });
  if (!r.ok) throw new Error(`Chat API returned ${r.status}`);
  return r.json();
}
